import{hitObject}from'./mechanics.js';
const pixels=new WeakMap(),images=new Map();
export function imageAlphaHit(image,u,v){if(!image||!(image.naturalWidth||image.width))return true;try{let data=pixels.get(image);if(!data){const canvas=document.createElement('canvas');canvas.width=image.naturalWidth||image.width;canvas.height=image.naturalHeight||image.height;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0);data={pixels:ctx.getImageData(0,0,canvas.width,canvas.height).data,w:canvas.width,h:canvas.height};pixels.set(image,data)}const x=Math.max(0,Math.min(data.w-1,Math.floor(u*data.w))),y=Math.max(0,Math.min(data.h-1,Math.floor(v*data.h)));return data.pixels[(y*data.w+x)*4+3]>12}catch{return true}}
export function preparePickImages(objects){for(const o of objects)if(o.asset&&!images.has(o.asset)){const image=new Image();image.src=o.asset;images.set(o.asset,image)}}
export function pick2D(objects,point){for(const o of [...objects].reverse()){if(o.hidden||['camera','trigger'].includes(o.type)||!hitObject(o,point))continue;if(o.asset){let image=images.get(o.asset);if(!image){image=new Image();image.src=o.asset;images.set(o.asset,image)}if(image.complete&&image.naturalWidth){const angle=-(o.rotation||0)*Math.PI/180,dx=point.x-o.x-o.w/2,dy=point.y-o.y-o.h/2,u=(dx*Math.cos(angle)-dy*Math.sin(angle)+o.w/2)/o.w,v=(dx*Math.sin(angle)+dy*Math.cos(angle)+o.h/2)/o.h;if(!imageAlphaHit(image,u,v))continue}}return o}return null}
export function touching2D(objects,player){const result=new Set();if(!player)return result;for(const o of objects){if(o===player||o.hidden||o.physics===false||['camera'].includes(o.type))continue;const epsilon=1.5;if(player.x<o.x+o.w+epsilon&&player.x+player.w>o.x-epsilon&&player.y<o.y+o.h+epsilon&&player.y+player.h>o.y-epsilon)result.add(o.id)}return result}
